95:     @Transactional
96:     public ResultadoLogin autenticar(String email, String senha, String origem) {
97:         String normalizado = NormalizadorEmail.normalizar(email);
98:         Usuario usuario = usuarioRepository.findWithLockByEmailNormalizado(normalizado).orElse(null);
99:         if (usuario == null) {
100:             passwordEncoder.matches(senha, hashFicticio);
101:             auditoria.registrar(null, "LOGIN", false, origem, "credenciais invalidas");
102:             return ResultadoLogin.falha();
103:         }
104: 
105:         Instant agora = Instant.now();
106:         usuario.desbloquearSeExpirado(agora);
107:         boolean senhaValida = usuario.getSenhaHash() != null
108:                 && passwordEncoder.matches(senha, usuario.getSenhaHash());
109:         if (usuario.getEstado() != EstadoConta.ATIVA || !senhaValida) {
110:             if (usuario.getEstado() == EstadoConta.ATIVA && !senhaValida) {
111:                 usuario.registrarFalha(agora);
112:             }
113:             auditoria.registrar(usuario.getId(), "LOGIN", false, origem, "credenciais ou estado invalidos");
114:             return ResultadoLogin.falha();
115:         }
116: 
117:         usuario.limparFalhas();
118:         auditoria.registrar(usuario.getId(), "LOGIN", true, origem, null);
119:         return ResultadoLogin.sucesso(UsuarioPrincipal.from(usuario));
