28:     private void verificar(String chave, int maximo, Duration janela) {
29:         Instant limite = Instant.now().minus(janela);
30:         Deque<Instant> instantes = requisicoes.computeIfAbsent(chave, ignorada -> new ArrayDeque<>());
31:         synchronized (instantes) {
32:             while (!instantes.isEmpty() && instantes.peekFirst().isBefore(limite)) {
33:                 instantes.removeFirst();
34:             }
35:             if (instantes.size() >= maximo) {
36:                 throw new LimiteTentativasException();
37:             }
38:             instantes.addLast(Instant.now());
39:         }
40:     }
41: }

