43:     private Long resolverUnidadeId() {
44:         if (unidadeId != null && unidadeId > 0) {
45:             return unidadeId;
46:         }
47:         if (nomeUnidade == null || nomeUnidade.isBlank()) {
48:             throw new IllegalArgumentException("bootstrap administrativo exige unidade valida");
49:         }
50:         var candidatas = unidadeRepository.findByNomeAndPrincipalTrue(nomeUnidade.trim());
51:         if (candidatas.size() > 1) {
52:             throw new ConflitoException("bootstrap ambiguo: informe AUTH_BOOTSTRAP_ADMIN_UNIT_ID");
53:         }
54:         return candidatas.isEmpty()
55:                 ? unidadeRepository.save(new Unidade(nomeUnidade.trim())).getId()
56:                 : candidatas.getFirst().getId();
57:     }
