# nginx interno do container do frontend.
# Serve o Angular compilado e encaminha /api e /actuator para o backend.
# Roda como usuario sem privilegio (uid 101) na porta 8080.

server {
    listen 8080;
    server_name _;

    root /usr/share/nginx/html;
    index index.html;

    server_tokens off;
    client_max_body_size 2m;

    # Verificacao de saude do container (usada pelo healthcheck do Compose).
    location = /healthz {
        access_log off;
        default_type text/plain;
        return 200 "ok\n";
    }

    # API e actuator vao para o backend na rede interna.
    location /api/ {
        proxy_pass http://backend:8080;
        proxy_http_version 1.1;
        proxy_set_header Host $host;
        proxy_set_header X-Real-IP $remote_addr;
        proxy_set_header X-Forwarded-For $proxy_add_x_forwarded_for;
        proxy_set_header X-Forwarded-Proto $scheme;
        proxy_set_header X-Forwarded-Host $host;
        proxy_read_timeout 60s;
    }

    location /actuator/ {
        proxy_pass http://backend:8080;
        proxy_http_version 1.1;
        proxy_set_header Host $host;
        proxy_set_header X-Real-IP $remote_addr;
        proxy_set_header X-Forwarded-For $proxy_add_x_forwarded_for;
        proxy_set_header X-Forwarded-Proto $scheme;
    }

    # Assets com hash no nome podem ser cacheados agressivamente.
    location ~* \.(?:css|js|woff2?|ttf|eot|png|jpe?g|gif|svg|ico|webp)$ {
        expires 30d;
        add_header Cache-Control "public, immutable";
        try_files $uri =404;
    }

    # SPA: qualquer rota desconhecida cai no index.html.
    location / {
        try_files $uri $uri/ /index.html;
        add_header Cache-Control "no-cache";
    }
}

# Zonas de limite e mapas de bloqueio do Estilo Marcado.
#
# Este arquivo e incluido no contexto `http` (via /etc/nginx/nginx.conf ->
# include /etc/nginx/conf.d/*.conf). As zonas so passam a valer onde forem
# referenciadas, portanto nao alteram o comportamento dos outros sites.

# --- Limites por IP ---------------------------------------------------------
# Navegacao geral (paginas e assets).
limit_req_zone $binary_remote_addr zone=em_geral:10m rate=30r/s;
# Chamadas de API comuns.
limit_req_zone $binary_remote_addr zone=em_api:10m rate=20r/s;
# Login: bem mais restrito (1 tentativa a cada 12s, com pequena rajada).
limit_req_zone $binary_remote_addr zone=em_login:10m rate=5r/m;
# Conexoes simultaneas por IP.
limit_conn_zone $binary_remote_addr zone=em_conn:10m;

# --- Bloqueio de scanners ---------------------------------------------------
# User-agents de ferramentas de varredura conhecidas (1 = bloquear).
map $http_user_agent $em_ua_suspeito {
    default 0;
    ""      1;
    ~*(nikto|sqlmap|nmap|masscan|acunetix|nessus|openvas|dirbuster|gobuster|wfuzz|hydra|medusa|zgrab|nuclei|jaeles|ffuf|feroxbuster|wpscan|xray|whatweb|skipfish|zap) 1;
}

# Caminhos tipicos de varredura, arquivos sensiveis e backups (1 = bloquear).
map $request_uri $em_path_suspeito {
    default 0;
    ~*(\.env|\.git|\.svn|\.hg|\.htaccess|\.htpasswd|\.DS_Store|wp-admin|wp-login|wp-content|wp-includes|xmlrpc\.php|phpmyadmin|pma|adminer|drupal|joomla|typo3|cgi-bin|/vendor/|/\.aws/|/\.ssh/|/\.well-known/acme-challenge/\.\.) 1;
    ~*\.(php|asp|aspx|jsp|cgi|pl|py|sh|rb|sql|bak|old|orig|swp|save|zip|tar|tgz|gz|rar|7z|env|ini|log|yml|yaml|json|lock|conf|config|pem|key|crt|p12|pfx)(\?.*)?$ 1;
}

# Arquivo de log proprio deste site (o fail2ban le daqui).
# Ajuste o caminho em conjunto com o jail se preferir separar dos demais sites.

# Cadeia de proxies confiaveis: o nginx do host esta na frente do container.
# Nao adicionamos nada aqui porque o backend ja usa forward-headers-strategy.

# Site de producao do Estilo Marcado.
#
# Instale em /etc/nginx/sites-available/estilomarcado.samuelsantos.qzz.io.conf
# e habilite com:
#   ln -s /etc/nginx/sites-available/estilomarcado.samuelsantos.qzz.io.conf \
#         /etc/nginx/sites-enabled/
#
# Antes do Certbot emitir o certificado, comente as linhas de ssl_* e o
# `listen 443 ssl` (ver deploy/README.md). O bloco da porta 80 ja responde ao
# desafio ACME via webroot em /var/www/certbot.

# --- HTTP: desafio ACME + redirecionamento para HTTPS -----------------------
server {
    listen 80;
    listen [::]:80;
    server_name estilomarcado.samuelsantos.qzz.io;

    location = /.well-known/acme-challenge/ {
        root /var/www/certbot;
    }

    location / {
        return 301 https://$host$request_uri;
    }
}

# --- HTTPS ------------------------------------------------------------------
server {
    listen 443 ssl;
    listen [::]:443 ssl;
    http2 on;
    server_name estilomarcado.samuelsantos.qzz.io;

    # Certificado emitido pelo Certbot (Let's Encrypt).
    ssl_certificate     /etc/letsencrypt/live/estilomarcado.samuelsantos.qzz.io/fullchain.pem;
    ssl_certificate_key /etc/letsencrypt/live/estilomarcado.samuelsantos.qzz.io/privkey.pem;
    ssl_trusted_certificate /etc/letsencrypt/live/estilomarcado.samuelsantos.qzz.io/chain.pem;
    include /etc/letsencrypt/options-ssl-nginx.conf;
    ssl_dhparam /etc/letsencrypt/ssl-dhparams.pem;

    # Renovacao do desafio ACME tambem sob HTTPS.
    location = /.well-known/acme-challenge/ {
        root /var/www/certbot;
    }

    # --- Endurecimento basico ------------------------------------------------
    server_tokens off;
    client_max_body_size 2m;
    client_header_timeout 15s;
    client_body_timeout 15s;
    send_timeout 30s;
    keepalive_timeout 30s;

    limit_conn em_conn 30;
    limit_req_status 429;
    limit_conn_status 429;

    # --- Cabecalhos de seguranca --------------------------------------------
    add_header Strict-Transport-Security "max-age=31536000; includeSubDomains" always;
    add_header X-Content-Type-Options "nosniff" always;
    add_header X-Frame-Options "DENY" always;
    add_header Referrer-Policy "strict-origin-when-cross-origin" always;
    add_header Permissions-Policy "geolocation=(), microphone=(), camera=(), payment=(), usb=()" always;
    # 'unsafe-inline' em style-src e necessario para o Angular. Nao ha scripts
    # inline; se o build passar a exigir, ajuste conscientemente.
    add_header Content-Security-Policy "default-src 'self'; script-src 'self'; style-src 'self' 'unsafe-inline'; img-src 'self' data: blob:; font-src 'self' data:; connect-src 'self'; object-src 'none'; base-uri 'self'; form-action 'self'; frame-ancestors 'none'" always;

    # IP real do cliente. Descomente e ajuste se estiver atras de Cloudflare/CDN.
    # set_real_ip_from 173.245.48.0/20;
    # set_real_ip_from 103.21.244.0/22;
    # set_real_ip_from 104.16.0.0/13;
    # real_ip_header CF-Connecting-IP;
    # real_ip_recursive on;

    # --- Bloqueio de scanners (conexao encerrada, sem resposta) --------------
    if ($em_ua_suspeito)   { return 444; }
    if ($em_path_suspeito) { return 444; }

    # Caminhos ocultos em geral.
    location ~ /\.(?!well-known) {
        return 444;
    }

    # Actuator nao e publico.
    location /actuator/ {
        return 404;
    }

    # --- Login: limite dedicado e mais rigoroso ------------------------------
    location = /api/autenticacao/sessoes {
        limit_req zone=em_login burst=3 nodelay;
        proxy_pass http://127.0.0.1:8081;
        include /etc/nginx/proxy_params_estilomarcado.conf;
    }

    # --- API ----------------------------------------------------------------
    location /api/ {
        limit_req zone=em_api burst=40 nodelay;
        proxy_pass http://127.0.0.1:8081;
        include /etc/nginx/proxy_params_estilomarcado.conf;
    }

    # --- Aplicacao (Angular) -------------------------------------------------
    location / {
        limit_req zone=em_geral burst=80 nodelay;
        proxy_pass http://127.0.0.1:8081;
        include /etc/nginx/proxy_params_estilomarcado.conf;
    }
}

# Cabecalhos de proxy usados pelo site do Estilo Marcado.
# Instale em /etc/nginx/proxy_params_estilomarcado.conf.
#
# O frontend (container) encaminha /api e /actuator ao backend. Estes headers
# garantem que o backend veja o IP real e o esquema HTTPS originais.

proxy_http_version 1.1;
proxy_set_header Host              $host;
proxy_set_header X-Real-IP         $remote_addr;
proxy_set_header X-Forwarded-For   $proxy_add_x_forwarded_for;
proxy_set_header X-Forwarded-Proto $scheme;
proxy_set_header X-Forwarded-Host  $host;
proxy_set_header X-Forwarded-Port  $server_port;
proxy_set_header Upgrade           $http_upgrade;
proxy_set_header Connection        "";

proxy_connect_timeout 10s;
proxy_send_timeout    60s;
proxy_read_timeout    60s;
proxy_buffering       on;

